DROP TABLE IF EXISTS `Holding`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Holding` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fundId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shares` decimal(20,4) NOT NULL,
  `costPrice` decimal(20,4) NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `sortOrder` int DEFAULT NULL,
  `accountId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `Holding_userId_fkey` (`userId`),
  KEY `Holding_fundId_fkey` (`fundId`),
  KEY `Holding_accountId_fkey` (`accountId`),
  CONSTRAINT `Holding_accountId_fkey` FOREIGN KEY (`accountId`) REFERENCES `Account` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Holding_fundId_fkey` FOREIGN KEY (`fundId`) REFERENCES `Fund` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `Holding_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

